{
  "implementation": "def solve(case):
    nodes = case['nodes']
    core_distance = case['core_distance']
    distances = case['distances']

    # Build list of edges with mutual reachability, canonicalize endpoints
    edges = []
    for u, v, d in distances:
        # Ensure canonical order: u < v lexicographically
        if u > v:
            u, v = v, u
        weight = max(core_distance[u], core_distance[v], d)
        edges.append((weight, u, v))

    # Sort by weight, then by u, then by v (all ties broken deterministically)
    edges.sort(key=lambda x: (x[0], x[1], x[2]))

    # Union-Find data structure
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    for weight, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, weight])
            total_weight += weight
            if len(mst_edges) == len(nodes) - 1:
                break

    if len(mst_edges) != len(nodes) - 1:
        raise ValueError('Graph is disconnected, cannot form a spanning tree')

    return {"mst_edges": mst_edges, "total_weight": total_weight}"
}
